"""SQL value semantics: NULL logic, operators, functions, and aggregates.

Public interface used by the engine.  Implementations must raise
:class:`minisql.errors.QueryError` for type errors and unknown functions.
"""

import re
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP, localcontext
from typing import Any, List, Optional

from .errors import QueryError


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------


def _is_number(value: Any) -> bool:
    """True for int/float but not bool (bool is an int subclass in Python)."""

    return isinstance(value, (int, float)) and not isinstance(value, bool)


def _type_name(value: Any) -> str:
    if value is None:
        return "NULL"
    if isinstance(value, bool):
        return "boolean"
    if isinstance(value, (int, float)):
        return "number"
    if isinstance(value, str):
        return "string"
    return type(value).__name__


def _kind(value: Any) -> str:
    """Comparison/sort family for a non-NULL value."""

    if isinstance(value, bool):
        return "bool"
    if isinstance(value, (int, float)):
        return "number"
    if isinstance(value, str):
        return "string"
    raise QueryError("cannot compare values of type %s" % _type_name(value))


def _require_number(value: Any, what: str) -> None:
    if not _is_number(value):
        raise QueryError("%s requires a number, got %s" % (what, _type_name(value)))


def _require_string(value: Any, what: str) -> None:
    if not isinstance(value, str):
        raise QueryError("%s requires a string, got %s" % (what, _type_name(value)))


def _sign(value: Any) -> int:
    return (value > 0) - (value < 0)


# ---------------------------------------------------------------------------
# Three-valued logic and conditions
# ---------------------------------------------------------------------------


def and3(a: Optional[bool], b: Optional[bool]) -> Optional[bool]:
    """Three-valued AND."""

    if a is False or b is False:
        return False
    if a is None or b is None:
        return None
    return True


def or3(a: Optional[bool], b: Optional[bool]) -> Optional[bool]:
    """Three-valued OR."""

    if a is True or b is True:
        return True
    if a is None or b is None:
        return None
    return False


def not3(a: Optional[bool]) -> Optional[bool]:
    """Three-valued NOT."""

    if a is None:
        return None
    return not a


def condition(value: Any) -> bool:
    """Interpret a value used by WHERE/HAVING: only TRUE keeps a row."""

    if value is None:
        return False
    if isinstance(value, bool):
        return value
    raise QueryError(
        "WHERE/HAVING condition must be boolean, got %s" % _type_name(value)
    )


# ---------------------------------------------------------------------------
# Arithmetic and concatenation
# ---------------------------------------------------------------------------


def arithmetic(op: str, a: Any, b: Any) -> Any:
    """Apply ``+``, ``-``, ``*`` or ``/`` with SQL typing and NULL rules."""

    if op not in ("+", "-", "*", "/"):
        raise QueryError("unknown arithmetic operator: %s" % op)

    if a is None or b is None:
        return None

    _require_number(a, "operator %s" % op)
    _require_number(b, "operator %s" % op)

    try:
        if op == "+":
            return a + b
        if op == "-":
            return a - b
        if op == "*":
            return a * b
        # op == "/"
        if b == 0:
            return None
        return a / b
    except OverflowError as exc:
        raise QueryError("arithmetic overflow") from exc
    except ZeroDivisionError:
        # Defensive: only reachable if a non-numeric zero slipped through.
        return None


def negate(a: Any) -> Any:
    """Unary minus."""

    if a is None:
        return None
    _require_number(a, "unary -")
    return -a


def concat(a: Any, b: Any) -> Any:
    """The ``||`` operator."""

    if a is None or b is None:
        return None
    return to_text(a) + to_text(b)


# ---------------------------------------------------------------------------
# Comparisons
# ---------------------------------------------------------------------------


def compare(op: str, a: Any, b: Any) -> Optional[bool]:
    """Apply ``= != <> < <= > >=`` returning None for a NULL operand."""

    if op not in ("=", "!=", "<>", "<", "<=", ">", ">="):
        raise QueryError("unknown comparison operator: %s" % op)

    if a is None or b is None:
        return None

    ka = _kind(a)
    kb = _kind(b)
    if ka != kb:
        raise QueryError(
            "cannot compare %s with %s" % (_type_name(a), _type_name(b))
        )

    if op == "=":
        return a == b
    if op in ("!=", "<>"):
        return a != b
    if op == "<":
        return a < b
    if op == "<=":
        return a <= b
    if op == ">":
        return a > b
    return a >= b  # op == ">="


def like(value: Any, pattern: Any) -> Optional[bool]:
    """SQL LIKE over the whole string, case-sensitive."""

    if value is None or pattern is None:
        return None
    if not isinstance(value, str) or not isinstance(pattern, str):
        raise QueryError(
            "LIKE requires strings, got %s and %s"
            % (_type_name(value), _type_name(pattern))
        )

    parts = ["\\A"]
    for char in pattern:
        if char == "%":
            parts.append(".*")
        elif char == "_":
            parts.append(".")
        else:
            parts.append(re.escape(char))
    parts.append("\\Z")

    return re.match("".join(parts), value, re.DOTALL) is not None


def in_list(value: Any, items: List[Any]) -> Optional[bool]:
    """SQL ``value IN (items...)`` with NULL semantics."""

    saw_null = value is None
    for item in items:
        result = compare("=", value, item)
        if result is True:
            return True
        if result is None:
            saw_null = True
    return None if saw_null else False


def between(value: Any, low: Any, high: Any) -> Optional[bool]:
    """SQL ``value BETWEEN low AND high`` with NULL semantics."""

    return and3(compare("<=", low, value), compare("<=", value, high))


# ---------------------------------------------------------------------------
# Scalar functions
# ---------------------------------------------------------------------------


def _round_to(value: Any, places: int) -> Decimal:
    """Round ``value`` to ``places`` decimals, ties away from zero."""

    if isinstance(value, float):
        # str() gives the shortest decimal that round-trips, which matches
        # the decimal literal the user wrote (e.g. 2.675 rather than its
        # binary approximation).
        number = Decimal(str(value))
    else:
        number = Decimal(value)

    exponent = Decimal(1).scaleb(-places)
    digits = len(number.as_tuple().digits)
    # Enough precision for both large integral parts and small fractions.
    precision = max(28, digits + abs(number.adjusted()) + max(0, places) + 5)

    with localcontext() as ctx:
        ctx.prec = precision
        try:
            return number.quantize(exponent, rounding=ROUND_HALF_UP)
        except (InvalidOperation, ValueError) as exc:
            raise QueryError("ROUND: value out of range") from exc


def scalar_function(name: str, args: List[Any]) -> Any:
    """Call a scalar function.  ``args`` are already evaluated."""

    fname = name.lower()

    if fname == "coalesce":
        if not args:
            raise QueryError("COALESCE requires at least one argument")
        for arg in args:
            if arg is not None:
                return arg
        return None

    arities = {
        "lower": (1,),
        "upper": (1,),
        "length": (1,),
        "abs": (1,),
        "round": (1, 2),
    }
    if fname not in arities:
        raise QueryError("unknown function: %s" % name)
    if len(args) not in arities[fname]:
        expected = " or ".join(str(n) for n in arities[fname])
        raise QueryError(
            "%s expects %s argument(s), got %d" % (name, expected, len(args))
        )

    # SQL: any NULL argument yields NULL (COALESCE handled above).
    if any(arg is None for arg in args):
        return None

    if fname == "lower":
        _require_string(args[0], "LOWER")
        return args[0].lower()

    if fname == "upper":
        _require_string(args[0], "UPPER")
        return args[0].upper()

    if fname == "length":
        _require_string(args[0], "LENGTH")
        return len(args[0])

    if fname == "abs":
        _require_number(args[0], "ABS")
        return abs(args[0])

    # ROUND
    value = args[0]
    _require_number(value, "ROUND")
    if len(args) == 1:
        return int(_round_to(value, 0))

    places = args[1]
    if not isinstance(places, int) or isinstance(places, bool):
        raise QueryError(
            "ROUND's second argument must be an integer, got %s"
            % _type_name(places)
        )
    return float(_round_to(value, places))


def is_aggregate(name: str) -> bool:
    """Return True for COUNT/SUM/AVG/MIN/MAX (case-insensitive)."""

    return name.lower() in ("count", "sum", "avg", "min", "max")


# ---------------------------------------------------------------------------
# Aggregates
# ---------------------------------------------------------------------------


def aggregate(name: str, values: List[Any]) -> Any:
    """Aggregate already-evaluated argument values (NULLs included).

    ``COUNT(*)`` is handled by the engine; for ``COUNT(expr)`` pass the
    per-row values and this counts non-NULL ones.
    """

    fname = name.lower()
    if fname not in ("count", "sum", "avg", "min", "max"):
        raise QueryError("unknown aggregate: %s" % name)

    if fname == "count":
        return sum(1 for value in values if value is not None)

    present = [value for value in values if value is not None]

    if fname in ("sum", "avg"):
        for value in present:
            if not _is_number(value):
                raise QueryError(
                    "%s requires numeric values, got %s"
                    % (name.upper(), _type_name(value))
                )
        if not present:
            return None

        if fname == "sum":
            try:
                return sum(present)
            except OverflowError as exc:
                raise QueryError("SUM overflow") from exc

        try:
            return float(sum(present)) / len(present)
        except OverflowError as exc:
            raise QueryError("AVG overflow") from exc

    # MIN / MAX
    if not present:
        return None
    best = present[0]
    for value in present[1:]:
        order = compare_for_sort(value, best)
        if (fname == "min" and order < 0) or (fname == "max" and order > 0):
            best = value
    return best


def compare_for_sort(a: Any, b: Any) -> int:
    """Compare two non-NULL values, returning -1, 0, or 1."""

    if a is None or b is None:
        raise QueryError("cannot sort NULL values with compare_for_sort")

    ka = _kind(a)
    kb = _kind(b)
    if ka != kb:
        raise QueryError(
            "cannot compare %s with %s" % (_type_name(a), _type_name(b))
        )

    if a == b:
        return 0
    return -1 if a < b else 1


# ---------------------------------------------------------------------------
# Grouping and text
# ---------------------------------------------------------------------------


def group_key(value: Any) -> Any:
    """Return a hashable key such that SQL-equal values share a key."""

    if value is None:
        return ("null",)
    if isinstance(value, bool):
        return ("bool", value)
    if isinstance(value, (int, float)):
        # 1 and 1.0 compare (and hash) equal in Python, as SQL requires.
        return ("number", value)
    if isinstance(value, str):
        return ("string", value)
    raise QueryError("cannot group value of type %s" % _type_name(value))


def row_key(values: List[Any]) -> tuple:
    """Return a hashable key for a whole row of values."""

    return tuple(group_key(value) for value in values)


def to_text(value: Any) -> str:
    """Text representation used by ``||`` and output formatting."""

    if value is None:
        return ""
    if isinstance(value, str):
        return value
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, (int, float)):
        return str(value)
    raise QueryError("cannot convert %s to text" % _type_name(value))

